// File: serie.cpp
#include "serie.h"

int tareas_pendientes(int hechas, int total) {
    return total - hechas;
}

std::string estado_serie(int hechas, int total) {
    if (tareas_pendientes(hechas, total) == 0) {
        return "Finished";
    }
    return "In progress";
}

// File: main.cpp
#include "serie.h"
#include <iostream>

int main() {
    std::cout << estado_serie(3, 5) << ": " << tareas_pendientes(3, 5) << "\n";
    std::cout << estado_serie(0, 0) << ": " << tareas_pendientes(0, 0) << "\n";
    std::cout << estado_serie(5, 5) << ": " << tareas_pendientes(5, 5);
    return 0;
}

